
import pandas as pd
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import (
    accuracy_score,
    balanced_accuracy_score,
    classification_report,
    confusion_matrix,
)

DATA_FILE = "gold_features.csv"

FEATURES = [
    "return_1h",
    "return_4h",
    "return_12h",
    "sma_5_gap",
    "sma_20_gap",
    "trend_5_20",
    "volatility_10",
    "volatility_20",
    "rsi_14",
]


def main():
    df = pd.read_csv(DATA_FILE)

    # Match the lowercase column names generated by features.py
    df.columns = df.columns.str.lower()

    if "datetime" not in df.columns:
        raise ValueError("Missing datetime column in gold_features.csv")

    df["datetime"] = pd.to_datetime(df["datetime"], errors="coerce")
    df = df.sort_values("datetime").reset_index(drop=True)

    required = FEATURES + ["target_up", "datetime"]
    missing = [col for col in required if col not in df.columns]

    if missing:
        raise ValueError(f"Missing required columns: {missing}")

    # Remove rows with incomplete features or unavailable target labels
    df = df.dropna(subset=FEATURES + ["target_up"]).copy()
    df["target_up"] = df["target_up"].astype(int)

    if df["target_up"].nunique() < 2:
        raise ValueError("The target contains only one class.")

    X = df[FEATURES]
    y = df["target_up"]

    # Chronological split: never shuffle time-series data
    split = int(len(df) * 0.80)
    X_train, X_test = X.iloc[:split], X.iloc[split:]
    y_train, y_test = y.iloc[:split], y.iloc[split:]

    print(f"Total usable rows: {len(df)}")
    print(f"Training rows: {len(X_train)}")
    print(f"Testing rows: {len(X_test)}")
    print(f"\nFeatures used: {len(FEATURES)}")

    print(
        f"\nTraining period: {df['datetime'].iloc[0]} "
        f"to {df['datetime'].iloc[split - 1]}"
    )
    print(
        f"Testing period: {df['datetime'].iloc[split]} "
        f"to {df['datetime'].iloc[-1]}"
    )

    # Majority-class baseline
    majority_class = y_train.mode().iloc[0]
    baseline_predictions = [majority_class] * len(y_test)

    print("\nBaseline accuracy:")
    print(f"{accuracy_score(y_test, baseline_predictions):.4f}")

    model = Pipeline([
        ("scaler", StandardScaler()),
        (
            "classifier",
            LogisticRegression(
                class_weight="balanced",
                max_iter=2000,
                random_state=42,
            ),
        ),
    ])

    model.fit(X_train, y_train)
    predictions = model.predict(X_test)

    print("\nLogistic Regression results")
    print(f"Accuracy: {accuracy_score(y_test, predictions):.4f}")
    print(
        "Balanced accuracy: "
        f"{balanced_accuracy_score(y_test, predictions):.4f}"
    )

    print("\nClassification report:")
    print(
        classification_report(
            y_test,
            predictions,
            labels=[0, 1],
            target_names=["Down / unchanged", "Up"],
            zero_division=0,
        )
    )

    print("Confusion matrix:")
    print(confusion_matrix(y_test, predictions, labels=[0, 1]))


if __name__ == "__main__":
    main()
